/* meta.c: generated by gcnmusicscraper. Ignores the region letter on purpose. */
extern const char **getEntries(char *gameId, int *count);

/* Files a rip lists that are data for another file, not audio at all, or
 * audio vgmstream can't play on its own: JAudio wave banks and their
 * sequence / bank / init files (Wind Waker, Sunshine...) only play through
 * the game's sequencer. */
static const char *const companion_exts[] = {
	"spd", "isd", "mid", "txt", "nfo", "7z", "bat", "log", "cfg", "bnr", "def",
	"tbl", "sdir", "pool", "proj", "fpk", "arc", "samp", "sys",
	"aw", "aaf", "baa", "bms", "bnk", "bst", "bstn", "ws", NULL
};

bool tracks_is_companion(const char *path) {
	const char *dot = strrchr(path, '.');
	if (!dot)
		return false;
	for (int i = 0; companion_exts[i]; i++)
		if (!strcasecmp(dot + 1, companion_exts[i]))
			return true;
	return false;
}

int tracks_key_split(const char *key, char *path, size_t size) {
	const char *h = strrchr(key, '#');
	if (h && h[1] && strspn(h + 1, "0123456789") == strlen(h + 1)) {
		snprintf(path, size, "%.*s", (int)(h - key), key);
		return atoi(h + 1);
	}
	snprintf(path, size, "%s", key);
	return 0;
}

void tracks_default_name(char *out, size_t size, const char *path) {
	char file[TRACK_KEY_MAX];
	int sub = tracks_key_split(path, file, sizeof(file));
	const char *base = strrchr(file, '/');
	base = base ? base + 1 : file;
	snprintf(out, size, "%s", base);
	char *dot = strrchr(out, '.');
	if (dot && dot != out)
		*dot = 0;
	if (sub > 0) {
		size_t n = strlen(out);
		snprintf(out + n, size - n, "_%05d", sub);
	}
}

/* Name endings vgmstream treats as the two halves of a stereo pair (left
 * first); see find_dual_file in vgmstream.c. The left half is what gets
 * played and listed, the right half rides along. */
static const struct { const char *left, *right; bool is_ext; } pair_suffixes[] = {
	{ "L", "R", false }, { "l", "r", false }, { "left", "right", false }, { "Left", "Right", false },
	{ "_0", "_1", false }, { "L", "R", true }, { "V0", "V1", true },
};

/* Matching suffix index for the left half of a pair, or -1. */
static int left_pair_suffix(const char *path) {
	const char *dot = strrchr(path, '.');
	const char *slash = strrchr(path, '/');
	if (!dot || (slash && dot < slash))
		return -1;
	for (int i = 0; i < (int)(sizeof(pair_suffixes) / sizeof(pair_suffixes[0])); i++) {
		size_t len = strlen(pair_suffixes[i].left);
		if (pair_suffixes[i].is_ext) {
			if (!strcmp(dot + 1, pair_suffixes[i].left))
				return i;
		} else if ((size_t)(dot - path) > len && !strncmp(dot - len, pair_suffixes[i].left, len)) {
			return i;
		}
	}
	return -1;
}

bool tracks_right_partner(const char *path, char *out, size_t size) {
	int i = left_pair_suffix(path);
	if (i < 0)
		return false;
	const char *dot = strrchr(path, '.');
	if (pair_suffixes[i].is_ext) {
		snprintf(out, size, "%.*s.%s", (int)(dot - path), path, pair_suffixes[i].right);
	} else {
		size_t stem = dot - path - strlen(pair_suffixes[i].left);
		snprintf(out, size, "%.*s%s%s", (int)stem, path, pair_suffixes[i].right, dot);
	}
	return true;
}

/* Default name for the left half of a pair: without the L, and without a
 * separator left dangling ("rui_samusL" -> "rui_samus", "track_L" -> "track"). */
static void pair_name(char *name, const char *path) {
	int i = left_pair_suffix(path);
	if (i < 0 || pair_suffixes[i].is_ext)
		return;
	size_t n = strlen(name), len = strlen(pair_suffixes[i].left);
	if (n <= len)
		return;
	name[n - len] = 0;
	n -= len;
	while (n > 1 && (name[n - 1] == '_' || name[n - 1] == '-' || name[n - 1] == ' '))
		name[--n] = 0;
}

void tracks_default_track_name(char *out, size_t size, const char *path, bool paired) {
	tracks_default_name(out, size, path);
	if (paired)
		pair_name(out, path);
}

/* Marks right halves whose left half is on the disc: they go with the left
 * one (backed up, not listed), and the left one is named without the L. */
static void find_pairs(TrackList *list) {
	for (int i = 0; i < list->count; i++) {
		Track *l = &list->tracks[i];
		char right[256];
		if (!l->file || l->subsong || l->paired || l->pair_left || !tracks_right_partner(l->file->path, right, sizeof(right)))
			continue;
		const DiscFile *rf = fst_find(right);
		if (!rf || rf == l->file)
			continue;
		for (int j = 0; j < list->count; j++) {
			Track *r = &list->tracks[j];
			if (r->file == rf && !r->subsong) {
				r->companion = true;
				r->pair_left = l;
			}
		}
		l->paired = true;
	}
}

const char *tracks_key(const Track *t) {
	return t->key;
}

/* ------------------------------------------------------------------ banks */

/* How many streams vgmstream finds in a disc file (0: it can't open it,
 * 1: an ordinary file). Each file is opened once per disc. */
static struct { const DiscFile *file; int count; } bank_cache[32];
static int bank_cached;

static int bank_count(const DiscFile *f) {
	for (int i = 0; i < bank_cached; i++)
		if (bank_cache[i].file == f)
			return bank_cache[i].count;
	int count = 0;
	libstreamfile_t *sf = disc_sf_open(f->path);
	if (sf) {
		libvgmstream_config_t cfg = {0};
		libvgmstream_t *lib = libvgmstream_create(sf, 0, &cfg);
		libstreamfile_close(sf);
		if (lib) {
			count = lib->format->subsong_count > 1 ? lib->format->subsong_count : 1;
			libvgmstream_free(lib);
		}
	}
	if (bank_cached < (int)(sizeof(bank_cache) / sizeof(bank_cache[0]))) {
		bank_cache[bank_cached].file = f;
		bank_cache[bank_cached++].count = count;
	}
	printf("tracks: %s has %d stream%s\r\n", f->path, count, count == 1 ? "" : "s");
	return count;
}

/* Rips split banks into one file per stream, numbered: "mpgcstr_00012.pdt"
 * is stream 12 of the disc's "mpgcstr.pdt". Only tried for an entry that
 * isn't on the disc, only for exactly five digits (shorter numbers are
 * ordinary file names), and only if vgmstream finds that many streams in
 * the file. Returns the subsong, 0 if it isn't one. */
static int split_bank_entry(const char *path, const DiscFile **file) {
	const char *dot = strrchr(path, '.');
	const char *slash = strrchr(path, '/');
	if (!dot || (slash && dot < slash) || dot - path < 7 || dot[-6] != '_')
		return 0;
	for (int i = 1; i <= 5; i++)
		if (dot[-i] < '0' || dot[-i] > '9')
			return 0;
	int sub = atoi(dot - 5);
	if (sub < 1)
		return 0;
	char base[TRACK_KEY_MAX];
	snprintf(base, sizeof(base), "%.*s%s", (int)(dot - 6 - path), path, dot);
	const DiscFile *f = fst_find(base);
	if (!f || bank_count(f) < sub || bank_count(f) < 2)
		return 0;
	*file = f;
	return sub;
}

static void init_track(Track *t, const char *path) {
	memset(t, 0, sizeof(*t));
	t->path = path;
	char file[TRACK_KEY_MAX];
	int sub = tracks_key_split(path, file, sizeof(file));
	t->file = fst_find(file);
	if (sub > 0) {
		/* "<path>#<n>" (from the names file): a stream of a bank */
		if (t->file && bank_count(t->file) >= sub)
			t->subsong = sub;
		else
			t->file = NULL;
	} else if (!t->file) {
		t->subsong = split_bank_entry(path, &t->file);
	}
	if (t->file && t->subsong)
		snprintf(t->key, sizeof(t->key), "%s#%d", t->file->path, t->subsong);
	else
		snprintf(t->key, sizeof(t->key), "%s", t->file ? t->file->path : path);
	t->companion = tracks_is_companion(file);
	tracks_default_name(t->name, sizeof(t->name), path);
}

/* strcasecmp, but runs of digits compare as numbers ("Track 2" before "Track 10") */
static int natural_cmp(const char *a, const char *b) {
	while (*a && *b) {
		if (isdigit((unsigned char)*a) && isdigit((unsigned char)*b)) {
			while (*a == '0') a++;
			while (*b == '0') b++;
			const char *ea = a, *eb = b;
			while (isdigit((unsigned char)*ea)) ea++;
			while (isdigit((unsigned char)*eb)) eb++;
			if (ea - a != eb - b)
				return (int)(ea - a) - (int)(eb - b);
			for (; a < ea; a++, b++)
				if (*a != *b)
					return *a - *b;
			continue;
		}
		int ca = tolower((unsigned char)*a), cb = tolower((unsigned char)*b);
		if (ca != cb)
			return ca - cb;
		a++;
		b++;
	}
	return (unsigned char)*a - (unsigned char)*b;
}

static const TrackList *sorting;

static int order_cmp(const void *pa, const void *pb) {
	const Track *a = &sorting->tracks[*(const int *)pa];
	const Track *b = &sorting->tracks[*(const int *)pb];
	int c = natural_cmp(a->name, b->name);
	return c ? c : strcasecmp(tracks_key(a), tracks_key(b));
}

static bool listable(const Track *t);

/* the list's order: every listable track, by the name it's shown with */
static void build_order(TrackList *list) {
	int *order = realloc(list->order, (list->count + 1) * sizeof(int));
	if (!order)
		return;
	list->order = order;
	int n = 0;
	for (int i = 0; i < list->count; i++)
		if (listable(&list->tracks[i]))
			order[n++] = i;
	sorting = list;
	qsort(order, n, sizeof(int), order_cmp);
	list->order_count = n;
}

void tracks_apply_names(TrackList *list) {
	for (int i = 0; i < list->count; i++) {
		Track *t = &list->tracks[i];
		const NameEntry *e = names_find(&list->names, tracks_key(t));
		t->hidden = e && e->hidden;
		t->custom_name = e && e->name;
		if (t->custom_name)
			snprintf(t->name, sizeof(t->name), "%s", e->name);
		else
			tracks_default_track_name(t->name, sizeof(t->name), tracks_key(t), t->paired);
	}
	if (list->names.title[0])
		snprintf(list->game_name, sizeof(list->game_name), "%s", list->names.title);
	build_order(list);
}

void tracks_refresh_sd(TrackList *list) {
	for (int i = 0; i < list->count; i++) {
		Track *t = &list->tracks[i];
		t->on_sd = false;
		if (!t->file)
			continue;
		char path[1024];
		struct stat st;
		backup_path(path, sizeof(path), list->game_id, t->file->path);
		t->on_sd = stat(path, &st) == 0 && st.st_size == t->file->size;
		/* a stream of a bank is listed on SD once it's been backed up itself
		 * (the names file says so: see backup_start) */
		if (t->on_sd && t->subsong) {
			const NameEntry *e = names_find(&list->names, t->key);
			t->on_sd = e && !strcasecmp(e->path, t->key);
		}
	}
}

int tracks_load_disc(TrackList *list, const char *game_id, const char *header_name) {
	tracks_free(list);
	bank_cached = 0;
	memcpy(list->game_id, game_id, 6);
	list->game_id[6] = 0;
	snprintf(list->game_name, sizeof(list->game_name), "%s", header_name ? header_name : "");

	names_load(&list->names, list->game_id);
	info_load(&list->info, list->game_id);

	int meta_count = 0;
	const char **entries = getEntries(list->game_id, &meta_count);
	if (!entries)
		meta_count = 0;

	/* room for every meta.c entry plus every names-file entry */
	list->tracks = calloc(meta_count + list->names.count + 1, sizeof(Track));
	if (!list->tracks)
		return 0;

	for (int i = 0; i < meta_count; i++)
		init_track(&list->tracks[list->count++], entries[i]);
	list->meta_count = meta_count;

	/* names-file paths meta.c doesn't know: add them (the same track on the
	 * disc, or the same path, counts as known) */
	for (int i = 0; i < list->names.count; i++) {
		const char *p = list->names.entries[i].path;
		Track *t = &list->tracks[list->count];
		init_track(t, p);
		bool known = false;
		for (int j = 0; j < list->count && !known; j++)
			known = (t->file && !strcasecmp(list->tracks[j].key, t->key)) || !strcasecmp(list->tracks[j].path, p);
		if (!known)
			list->count++;
	}

	for (int i = 0; i < list->count; i++) {
		if (list->tracks[i].file) {
			list->found++;
			if (i < meta_count)
				list->meta_found++;
			else
				list->extra_found++;
		} else
			printf("tracks: not on disc: %s\r\n", list->tracks[i].path);
	}
	find_pairs(list);
	tracks_apply_names(list);
	tracks_refresh_sd(list);
	printf("tracks: %s: %d of %d entries found\r\n", list->game_id, list->found, list->count);
	return tracks_visible_count(list);
}

/* ----------------------------------------------------------- disc search */

#define SCAN_MIN_SIZE   (48 * 1024)   /* smaller than this: a sound effect */
#define SCAN_MIN_SECS   8             /* shorter (and not looping): a sound effect or jingle */

typedef struct { const DiscFile *file; int subsong; } Found;

static bool listed(const TrackList *list, const DiscFile *f, int subsong) {
	for (int i = 0; i < list->count; i++)
		if (list->tracks[i].file == f && list->tracks[i].subsong == subsong)
			return true;
	return false;
}

static libvgmstream_t *open_stream(const DiscFile *f, int subsong) {
	libstreamfile_t *sf = disc_sf_open(f->path);
	if (!sf)
		return NULL;
	libvgmstream_config_t cfg = {0};
	cfg.loop_count = audio_settings.loop_count;   /* (as the player would: the info cache keeps the length) */
	cfg.fade_time = audio_settings.fade_seconds;
	cfg.auto_downmix_channels = 2;
	cfg.force_sfmt = LIBVGMSTREAM_SFMT_PCM16;
	libvgmstream_t *lib = libvgmstream_create(sf, subsong, &cfg);
	libstreamfile_close(sf);
	return lib;
}

static bool add_found(Found **found, int *nf, int *cap, const DiscFile *f, int subsong) {
	if (*nf == *cap) {
		int c = *cap ? *cap * 2 : 64;
		Found *n = realloc(*found, c * sizeof(Found));
		if (!n)
			return false;
		*found = n;
		*cap = c;
	}
	(*found)[(*nf)++] = (Found){ f, subsong };
	return true;
}

/* Opens f with vgmstream. An ordinary file counts if it's long enough (or
 * loops) to be music; a bank (more than one stream) is music already, so
 * every stream in it that isn't listed yet is added, short ones too. */
static void probe(TrackList *list, const DiscFile *f, Found **found, int *nf, int *cap) {
	libvgmstream_t *lib = open_stream(f, 0);
	if (!lib)
		return;
	const libvgmstream_format_t *fmt = lib->format;
	int streams = fmt->subsong_count;
	if (streams <= 1) {
		bool music = !listed(list, f, 0) && fmt->sample_rate > 0 &&
		             (fmt->loop_flag || fmt->stream_samples >= (int64_t)SCAN_MIN_SECS * fmt->sample_rate);
		if (music && add_found(found, nf, cap, f, 0))
			info_record(&list->info, f->path, fmt);
		libvgmstream_free(lib);
		return;
	}
	libvgmstream_free(lib);
	for (int s = 1; s <= streams; s++) {
		if (listed(list, f, s))
			continue;
		libvgmstream_t *sl = open_stream(f, s);
		if (!sl)
			continue;
		char key[TRACK_KEY_MAX];
		snprintf(key, sizeof(key), "%s#%d", f->path, s);
		if (add_found(found, nf, cap, f, s))
			info_record(&list->info, key, sl->format);
		libvgmstream_free(sl);
	}
}

/* the names table's own copy of path (it lives as long as the list) */
static const char *names_path(NameTable *names, const char *path) {
	names_add(names, path);
	for (int i = 0; i < names->count; i++)
		if (!strcasecmp(names->entries[i].path, path))
			return names->entries[i].path;
	return NULL;
}

int tracks_scan_disc(TrackList *list, ScanProgress *p) {
	int n = fst_count();
	const DiscFile **cand = malloc((n + 1) * sizeof(*cand));
	Found *found = NULL;
	int nc = 0, nf = 0, cap = 0;
	p->done = p->total = p->found = 0;
	if (!cand)
		return 0;

	/* the files vgmstream might play, by extension (vgmstream's list, and
	 * whatever this game's meta.c entries use: the rip may have renamed the
	 * files, but not changed what they are). Files already listed whole are
	 * skipped; banks are looked at again for streams not listed yet. */
	int meta_count = 0;
	const char **entries = getEntries(list->game_id, &meta_count);
	libvgmstream_valid_t valid = { .reject_extensionless = true, .accept_common = true };
	for (int i = 0; i < n; i++) {
		const DiscFile *f = fst_file(i);
		if (f->size < SCAN_MIN_SIZE || tracks_is_companion(f->path) || listed(list, f, 0))
			continue;
		bool known = libvgmstream_is_valid(f->path, &valid);
		const char *ext = strrchr(f->path, '.');
		for (int j = 0; !known && ext && entries && j < meta_count; j++) {
			const char *e = strrchr(entries[j], '.');
			known = e && !strcasecmp(e, ext);
		}
		if (known)
			cand[nc++] = f;
	}
	p->total = nc;

	for (int i = 0; i < nc && !p->cancel; i++) {
		p->done = i;
		probe(list, cand[i], &found, &nf, &cap);
		p->found = nf;
	}
	p->done = nc;
	free(cand);

	if (nf) {
		Track *t = realloc(list->tracks, (list->count + nf + 1) * sizeof(Track));
		if (t) {
			list->tracks = t;
			int added = 0;
			for (int i = 0; i < nf; i++) {
				char key[TRACK_KEY_MAX];
				if (found[i].subsong)
					snprintf(key, sizeof(key), "%s#%d", found[i].file->path, found[i].subsong);
				else
					snprintf(key, sizeof(key), "%s", found[i].file->path);
				const char *path = names_path(&list->names, key);
				if (!path)
					continue;
				init_track(&list->tracks[list->count++], path);
				list->found++;
				added++;
			}
			nf = added;
			/* pairs again, from scratch (the array moved, and new halves may have turned up) */
			for (int i = 0; i < list->count; i++) {
				Track *tr = &list->tracks[i];
				char file[TRACK_KEY_MAX];
				tracks_key_split(tr->path, file, sizeof(file));
				tr->paired = false;
				tr->pair_left = NULL;
				tr->companion = tracks_is_companion(file);
			}
			find_pairs(list);
			tracks_apply_names(list);
			tracks_refresh_sd(list);
			names_save(&list->names);
		} else {
			nf = 0;
		}
	}
	free(found);
	p->found = nf;
	printf("tracks: search found %d tracks in %d candidate files\r\n", nf, nc);
	return nf;
}

void tracks_free(TrackList *list) {
	free(list->tracks);
	free(list->order);
	names_free(&list->names);
	info_free(&list->info);
	memset(list, 0, sizeof(*list));
}

static bool listable(const Track *t) {
	return t->file && !t->companion && !t->hidden;
}

int tracks_visible_count(const TrackList *list) {
	return list->order ? list->order_count : 0;
}

Track *tracks_visible(TrackList *list, int index) {
	if (!list->order || index < 0 || index >= list->order_count)
		return NULL;
	return &list->tracks[list->order[index]];
}
